import { existsSync } from 'node:fs';
import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { aggregateReliability } from './lib/reliability-aggregation.mjs';

const ROOT = process.cwd();
const OUT_DIR = resolve(ROOT, 'artifacts/agent-dev-benefit-eval');

async function read(path) {
  return await readFile(resolve(ROOT, path), 'utf8');
}

async function walk(dir, predicate = () => true) {
  const results = [];
  async function visit(abs) {
    for (const entry of await readdir(abs, { withFileTypes: true })) {
      if (entry.name === 'node_modules' || entry.name === '.git' || entry.name === 'dist') continue;
      const full = join(abs, entry.name);
      if (entry.isDirectory()) await visit(full);
      else if (predicate(full)) results.push(full);
    }
  }
  await visit(resolve(ROOT, dir));
  return results;
}

function countMatches(text, pattern) {
  return [...text.matchAll(pattern)].length;
}

function extractScenarioIds(registryText) {
  const match = registryText.match(/export const AGENT_DEV_SCENARIOS = \[([\s\S]*?)\] as const/);
  return match ? [...match[1].matchAll(/\{\s*id:\s*'([^']+)'/g)].map((entry) => entry[1]) : [];
}

function packageInstalled(name) {
  const normalized = name.startsWith('@') ? name.replace('/', '\\') : name;
  return existsSync(resolve(ROOT, 'node_modules', ...normalized.split(/[\\/]/)));
}

async function scanSelectorCoverage() {
  const files = await walk('src', (file) => /\.(tsx|ts)$/.test(file));
  let testIdCount = 0;
  let interactiveTagCount = 0;
  let interactiveWithoutInlineTestId = 0;
  for (const file of files) {
    const text = await readFile(file, 'utf8');
    testIdCount += countMatches(text, /data-testid=/g);
    const tags = [...text.matchAll(/<(?<tag>button|input|select|textarea|a)\b(?<attrs>[^>]*)>/g)];
    interactiveTagCount += tags.length;
    interactiveWithoutInlineTestId += tags.filter((match) => !String(match.groups?.attrs ?? '').includes('data-testid')).length;
  }
  return {
    fileCount: files.length,
    testIdCount,
    interactiveTagCount,
    interactiveWithoutInlineTestId,
    inlineSelectorCoverage: interactiveTagCount === 0 ? 1 : Number(((interactiveTagCount - interactiveWithoutInlineTestId) / interactiveTagCount).toFixed(3)),
  };
}

function renderMarkdown(report) {
  const tools = report.externalTools.map((tool) => `| ${tool.package} | ${tool.installed ? 'yes' : 'no'} | ${tool.role} |`).join('\n');
  const reliability = report.reliability;
  return `# Agent Dev Benefit Evaluation

Generated: ${report.generatedAt}

## Summary

| Metric | Value |
| --- | ---: |
| Dev scenarios | ${report.agentDev.scenarioCount} |
| hostApi.agentDev methods | ${report.agentDev.hostApiMethodCount} |
| E2E agent-dev helpers | ${report.agentDev.e2eHelperCount} |
| Runtime schema assertions | ${report.agentDev.schemaAssertionCount} |
| Basic a11y rule families | ${report.quality.a11yRuleCount} |
| Renderer files scanned | ${report.selectorCoverage.fileCount} |
| data-testid occurrences | ${report.selectorCoverage.testIdCount} |
| Interactive tags scanned | ${report.selectorCoverage.interactiveTagCount} |
| Inline selector coverage | ${Math.round(report.selectorCoverage.inlineSelectorCoverage * 100)}% |

## External Tool Readiness

| Package | Installed | Role |
| --- | --- | --- |
${tools}

## Reliability Aggregation

This section uses the pre-registered deterministic oracle fixture. It is not real-provider, human-review, or generalization evidence.

| Metric | Value |
| --- | ---: |
| Registered k | ${reliability.k} |
| Raw case denominator | ${reliability.rawDenominator} |
| Complete case denominator | ${reliability.completeDenominator} |
| pass^k (all k succeeded) | ${reliability.passPowerK} |
| pass@k (at least one succeeded) | ${reliability.passAtK} |
| Flake rate | ${reliability.flakeRate} |
| Incomplete cases | ${reliability.incompleteCount} |
| Gate | ${reliability.gate} |

Reasons: ${reliability.reasons.length > 0 ? reliability.reasons.join('; ') : 'none'}

Missing cases: ${reliability.incompleteByOutcome.missing}; timeout cases: ${reliability.incompleteByOutcome.timeout}; crash cases: ${reliability.incompleteByOutcome.crash}; skip cases: ${reliability.incompleteByOutcome.skip}.

## Interpretation

- The current in-repo implementation already gives agents ${report.agentDev.scenarioCount} deterministic page entry points and ${report.agentDev.e2eHelperCount} E2E helpers without depending on new packages.
- Schema assertions now reject malformed agent-dev payloads at the Main host-api boundary.
- Basic a11y and visual artifact generation are available through Playwright today; axe/Argos can replace the fallback scanners once supply-chain policy allows installing them.
- The selector coverage metric is a heuristic. It is useful as a trend line, not as a precise accessibility or E2E quality proof.
- pass^k and pass@k are distinct. Incomplete cases are retained but excluded from denominators; the first failed trial remains recorded and is not erased by a retry.
`;
}

const start = performance.now();
const [scenarioRegistry, hostApi, e2eFixture, schemaText, a11yText, reliabilityFixtureText] = await Promise.all([
  read('shared/agent-dev/scenarios.ts'),
  read('src/lib/host-api.ts'),
  read('tests/e2e/fixtures/electron.ts'),
  read('shared/host-api/agent-dev-schemas.ts'),
  read('tests/e2e/fixtures/a11y.ts'),
  read('shared/agent-dev/reliability-fixture.json'),
]);

const scenarioIds = extractScenarioIds(scenarioRegistry);
const hostApiAgentDevBlock = hostApi.match(/agentDev:\s*\{([\s\S]*?)\n  \},\n  providers:/)?.[1] ?? '';
const report = {
  generatedAt: new Date().toISOString(),
  durationMs: 0,
  agentDev: {
    scenarioCount: scenarioIds.length,
    scenarios: scenarioIds,
    hostApiMethodCount: countMatches(hostApiAgentDevBlock, /^\s{4}[A-Za-z][A-Za-z0-9_]*:/gm),
    e2eHelperCount: countMatches(e2eFixture, /export async function (openAgentDevScenario|getAgentDevSnapshot|configureAgentDevHostReplay|getAgentDevHostCalls)/g),
    schemaAssertionCount: countMatches(schemaText, /export function assertAgentDev/g),
  },
  quality: {
    a11yRuleCount: countMatches(a11yText, /add\('([^']+)'/g),
    visualArtifactSpec: existsSync(resolve(ROOT, 'tests/e2e/agent-dev-quality.spec.ts')),
    workbenchScript: existsSync(resolve(ROOT, 'scripts/agent-dev-workbench.mjs')),
  },
  selectorCoverage: await scanSelectorCoverage(),
  reliability: aggregateReliability(JSON.parse(reliabilityFixtureText)),
  externalTools: [
    { package: '@axe-core/playwright', installed: packageInstalled('@axe-core/playwright'), role: 'strict a11y scanning' },
    { package: '@ladle/react', installed: packageInstalled('@ladle/react'), role: 'component scenario workbench' },
    { package: '@argos-ci/playwright', installed: packageInstalled('@argos-ci/playwright'), role: 'hosted visual regression' },
    { package: '@vitest/browser', installed: packageInstalled('@vitest/browser'), role: 'browser component testing' },
    { package: '@testing-library/user-event', installed: packageInstalled('@testing-library/user-event'), role: 'realistic component interactions' },
    { package: 'knip', installed: packageInstalled('knip'), role: 'unused files/deps/exports' },
    { package: 'ajv', installed: packageInstalled('ajv'), role: 'JSON schema validation engine' },
  ],
};
report.durationMs = Number((performance.now() - start).toFixed(1));

await mkdir(OUT_DIR, { recursive: true });
await writeFile(resolve(OUT_DIR, 'report.json'), JSON.stringify(report, null, 2), 'utf8');
await writeFile(resolve(OUT_DIR, 'report.md'), renderMarkdown(report), 'utf8');
console.log(JSON.stringify(report, null, 2));
"},{"path":"harness/specs/tasks/harness-gap-reliability-aggregation.md","content":"# E01 — Deterministic reliability aggregation

## Goal

Extend the existing Agent Dev benefit report with deterministic pass^k, per-trial success, flake detection, and positive/negative anchor aggregation. Reuse `shared/agent-dev/scenarios.ts` and the existing report; do not create another metrics platform.

## Pre-registration

The parameters live in `shared/agent-dev/reliability-fixture.json` before evaluation:

- `k = 3`
- `minCases = 20` complete cases
- `flakeThreshold = 0.05`

The fixture is an explicit deterministic oracle. It is not evidence from a real provider, a human reviewer, or an unseen workload.

## Aggregation contract

- A complete case has exactly `k` terminal trials.
- pass^k is the proportion of complete cases for which every trial achieved the expected result.
- pass@k is the proportion of complete cases for which at least one trial achieved the expected result.
- These metrics are always reported in separate fields and must not be renamed or conflated.
- Missing, timeout, crash, and skip cases are retained individually, counted as incomplete, and excluded from both metric denominators.
- A flake is a case whose first trial failed and a later fixed retry succeeded. The first failure remains in the report and a retry does not erase the original gate failure.
- Positive anchors must pass in all trials. Negative anchors must be rejected in all trials. Any violation fails the gate.
- Safety-required cases permit neither skip nor flake.
- Fewer than the registered number of complete cases yields `gate=insufficient-sample`; a small sample must never be presented as PASS.

## Output

The JSON and Markdown benefit reports include raw and complete denominators, pass^k, pass@k, flake rate, incomplete outcomes, anchors, safety findings, gate, and reasons.

## Boundaries

Do not change product defaults, product locks, approval semantics, user-visible interfaces, dependency configuration, or scheduling behavior. This is an internal evaluation-report change only, so README translations do not require modification.
"},{"path":"harness/specs/rules/reliability-aggregation-boundary.md","content":"# Reliability aggregation boundary

1. The scenario registry remains the source of Agent Dev scenarios. The reliability fixture may reference scenario identifiers but does not create a second scenario platform.
2. `k`, `minCases`, and `flakeThreshold` are fixture pre-registration parameters and are reported with the result.
3. Only complete cases enter pass^k and pass@k denominators. Raw denominator and every incomplete case remain visible.
4. pass^k means all k trials succeeded. pass@k means at least one trial succeeded. Their identifiers, labels, numerator, and denominator are never interchanged.
5. Missing, timeout, crash, and skip are incomplete outcomes. They are not silently dropped and are not counted as successes.
6. Flake detection is first-failure/later-success over fixed retries. Trial history is preserved. A successful retry does not retroactively change the first trial or satisfy the original gate by itself.
7. Positive anchors require all passes; negative anchors require all rejections. Any anchor violation fails the gate.
8. Safety-required cases have zero skips and zero flakes.
9. A complete sample below the registered minimum is `insufficient-sample`, never PASS.
10. The fixture is a deterministic oracle and must be labelled as such. It cannot support claims about a real provider, human users, production behavior, or generalization.
11. This reporting module must not alter product defaults, locks, approval behavior, dependency configuration, or automation schedules.
"},{"path":"docs/dev/harness-gap-closure/e01-reliability-aggregation.md","content":"# E01 reliability aggregation closure

## Scope

This change is limited to the internal Agent Dev benefit report and its deterministic reliability fixture. It reuses the existing scenario registry and report writer. No user-visible interface, public configuration, product default, product lock, approval semantic, dependency, or scheduled automation is changed.

## Implementation

- `scripts/lib/reliability-aggregation.mjs` provides the pure aggregation boundary.
- `scripts/agent-dev-benefit-eval.mjs` reads the pre-registered fixture and publishes reliability data in `report.json` and `report.md`.
- `shared/agent-dev/reliability-fixture.json` registers `k=3`, minimum complete cases `20`, and flake threshold `0.05`, followed by explicit deterministic trial outcomes.

The report distinguishes:

- pass^k: all k trials achieved the expected result.
- pass@k: at least one trial achieved the expected result.
- flake: the first trial failed and a later fixed retry succeeded.

Missing, timeout, crash, and skip cases remain visible as incomplete and are excluded from metric denominators. The original first failure remains visible. Positive anchors require every trial to pass, negative anchors require every trial to be rejected, and safety cases require zero skip and zero flake. Fewer than 20 complete cases produces `insufficient-sample`.

## Evidence boundary

The fixture is a deterministic oracle for internal report verification. It is explicitly not a real-provider benchmark, human evaluation, production sample, or evidence of generalization.

## Acceptance record

The implementation and fixture provide deterministic coverage for the requested metrics and gate rules. The clean-candidate fast gate consists of targeted unit tests, runtime/core type checks, scoped lint, and harness validate/dry-run. Credential scanning must report zero hits, and `SHA256SUMS` must be readable. These checks are recorded by the candidate validation procedure rather than simulated in this document.

README review across English, Chinese, Japanese, and Korean found no documented user-visible API or configuration change. README files therefore remain unchanged; this closure record captures the conclusion.
"}]}

