{"edits":[{"path":"scripts/lib/reliability-aggregation.mjs","content":"const TERMINAL_OUTCOMES = new Set(['pass', 'fail', 'rejected']);
const INCOMPLETE_OUTCOMES = new Set(['missing', 'timeout', 'crash', 'skip']);
const ALL_OUTCOMES = new Set([...TERMINAL_OUTCOMES, ...INCOMPLETE_OUTCOMES]);

function assertInteger(value, name) {
  if (!Number.isInteger(value) || value < 1) throw new TypeError(`${name} must be a positive integer`);
}

function outcomeCounts(cases) {
  const counts = { pass: 0, fail: 0, rejected: 0, missing: 0, timeout: 0, crash: 0, skip: 0 };
  for (const testCase of cases) {
    for (const trial of testCase.trials ?? []) {
      if (Object.hasOwn(counts, trial.outcome)) counts[trial.outcome] += 1;
    }
  }
  return counts;
}

function expectedSuccess(trial, anchor) {
  if (anchor === 'positive') return trial.outcome === 'pass';
  if (anchor === 'negative') return trial.outcome === 'rejected';
  return trial.outcome === 'pass';
}

function caseSummary(testCase, k, anchor) {
  const trials = testCase.trials ?? [];
  const incomplete = trials.some((trial) => INCOMPLETE_OUTCOMES.has(trial.outcome)) || trials.length !== k;
  const successfulTrials = trials.filter((trial) => expectedSuccess(trial, anchor));
  const first = trials[0];
  const flake = Boolean(
    first
    && first.outcome === 'fail'
    && trials.slice(1).some((trial) => expectedSuccess(trial, anchor)),
  );
  return {
    id: testCase.id,
    scenarioId: testCase.scenarioId ?? testCase.id,
    anchor: anchor ?? null,
    safety: Boolean(testCase.safety),
    complete: !incomplete,
    incomplete,
    passedAll: !incomplete && successfulTrials.length === k,
    passedAtLeastOnce: !incomplete && successfulTrials.length > 0,
    flake,
    firstTrialPassed: first ? expectedSuccess(first, anchor) : false,
    trials: trials.map((trial, index) => ({
      trial: index + 1,
      outcome: trial.outcome,
      expectedSuccess: expectedSuccess(trial, anchor),
    })),
  };
}

/**
 * Aggregate deterministic trial fixtures. A case is complete only when every one of
 * its k trials has a terminal outcome. Missing/timeout/crash/skip cases remain in
 * the report but are excluded from metric denominators.
 */
export function aggregateReliability(fixture) {
  const k = fixture.k;
  const minCases = fixture.minCases;
  const flakeThreshold = fixture.flakeThreshold;
  assertInteger(k, 'fixture.k');
  assertInteger(minCases, 'fixture.minCases');
  if (!Number.isFinite(flakeThreshold) || flakeThreshold < 0 || flakeThreshold > 1) {
    throw new TypeError('fixture.flakeThreshold must be between 0 and 1');
  }
  if (!Array.isArray(fixture.cases)) throw new TypeError('fixture.cases must be an array');

  const summaries = fixture.cases.map((testCase) => {
    if (!testCase || typeof testCase.id !== 'string') throw new TypeError('each fixture case requires an id');
    if (!Array.isArray(testCase.trials)) throw new TypeError(`fixture case ${testCase.id} requires trials`);
    for (const trial of testCase.trials) {
      if (!ALL_OUTCOMES.has(trial?.outcome)) throw new TypeError(`fixture case ${testCase.id} has an unknown trial outcome`);
    }
    const anchor = testCase.anchor ?? null;
    if (anchor !== null && anchor !== 'positive' && anchor !== 'negative') {
      throw new TypeError(`fixture case ${testCase.id} has an invalid anchor`);
    }
    return caseSummary(testCase, k, anchor);
  });

  const completeCases = summaries.filter((item) => item.complete);
  const incompleteCases = summaries.filter((item) => !item.complete);
  const rawDenominator = summaries.length;
  const completeDenominator = completeCases.length;
  const passedAll = completeCases.filter((item) => item.passedAll).length;
  const passedAtLeastOnce = completeCases.filter((item) => item.passedAtLeastOnce).length;
  const flakyCases = completeCases.filter((item) => item.flake);
  const passPowerK = completeDenominator === 0 ? 0 : passedAll / completeDenominator;
  const passAtK = completeDenominator === 0 ? 0 : passedAtLeastOnce / completeDenominator;
  const flakeRate = completeDenominator === 0 ? 0 : flakyCases.length / completeDenominator;

  const positives = completeCases.filter((item) => item.anchor === 'positive');
  const negatives = completeCases.filter((item) => item.anchor === 'negative');
  const positiveFailures = positives.filter((item) => !item.passedAll).map((item) => item.id);
  const negativeFailures = negatives.filter((item) => !item.passedAll).map((item) => item.id);
  const safetySkips = summaries.filter((item) => item.safety && item.trials.some((trial) => trial.outcome === 'skip')).map((item) => item.id);
  const safetyFlakes = summaries.filter((item) => item.safety && item.flake).map((item) => item.id);

  const reasons = [];
  if (completeDenominator < minCases) reasons.push(`complete sample ${completeDenominator} is below the registered minimum ${minCases}`);
  if (positiveFailures.length > 0) reasons.push(`positive anchor failures: ${positiveFailures.join(', ')}`);
  if (negativeFailures.length > 0) reasons.push(`negative anchor failures: ${negativeFailures.join(', ')}`);
  if (safetySkips.length > 0) reasons.push(`safety cases skipped: ${safetySkips.join(', ')}`);
  if (safetyFlakes.length > 0) reasons.push(`safety cases flaked: ${safetyFlakes.join(', ')}`);
  if (flakeRate > flakeThreshold) reasons.push(`flake rate ${flakeRate.toFixed(4)} exceeds threshold ${flakeThreshold.toFixed(4)}`);

  let gate = 'pass';
  if (completeDenominator < minCases) gate = 'insufficient-sample';
  else if (positiveFailures.length > 0 || negativeFailures.length > 0 || safetySkips.length > 0 || safetyFlakes.length > 0 || flakeRate > flakeThreshold) gate = 'fail';

  return {
    oracle: 'deterministic-fixture',
    realProviderEvidence: false,
    humanEvidence: false,
    generalizationClaim: false,
    k,
    minCases,
    flakeThreshold,
    rawDenominator,
    completeDenominator,
    incompleteCount: incompleteCases.length,
    passedAll,
    passedAtLeastOnce,
    passPowerK: Number(passPowerK.toFixed(6)),
    passAtK: Number(passAtK.toFixed(6)),
    flakyCaseCount: flakyCases.length,
    flakeRate: Number(flakeRate.toFixed(6)),
    incompleteByOutcome: {
      missing: incompleteCases.filter((item) => item.trials.some((trial) => trial.outcome === 'missing')).length,
      timeout: incompleteCases.filter((item) => item.trials.some((trial) => trial.outcome === 'timeout')).length,
      crash: incompleteCases.filter((item) => item.trials.some((trial) => trial.outcome === 'crash')).length,
      skip: incompleteCases.filter((item) => item.trials.some((trial) => trial.outcome === 'skip')).length,
    },
    trialOutcomes: outcomeCounts(summaries),
    anchors: {
      positive: { caseCount: positives.length, failures: positiveFailures },
      negative: { caseCount: negatives.length, failures: negativeFailures },
    },
    safety: { skippedCaseIds: safetySkips, flakyCaseIds: safetyFlakes },
    gate,
    reasons,
    cases: summaries,
  };
}
"},{"path":"scripts/lib/reliability-aggregation.d.mts","content":"export type ReliabilityOutcome =
  | 'pass'
  | 'fail'
  | 'rejected'
  | 'missing'
  | 'timeout'
  | 'crash'
  | 'skip';

export interface ReliabilityTrial {
  outcome: ReliabilityOutcome;
