}

export interface ReliabilityAggregation {
  oracle: 'deterministic-fixture';
  realProviderEvidence: false;
  humanEvidence: false;
  generalizationClaim: false;
  k: number;
  minCases: number;
  flakeThreshold: number;
  rawDenominator: number;
  completeDenominator: number;
  incompleteCount: number;
  passedAll: number;
  passedAtLeastOnce: number;
  passPowerK: number;
  passAtK: number;
  flakyCaseCount: number;
  flakeRate: number;
  incompleteByOutcome: Record<'missing' | 'timeout' | 'crash' | 'skip', number>;
  trialOutcomes: Record<ReliabilityOutcome, number>;
  anchors: {
    positive: { caseCount: number; failures: string[] };
    negative: { caseCount: number; failures: string[] };
  };
  safety: { skippedCaseIds: string[]; flakyCaseIds: string[] };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: string[];
  cases: ReliabilityCaseSummary[];
}

export function aggregateReliability(fixture: ReliabilityFixture): ReliabilityAggregation;
